const MOD = 998244353n;
const INV = 499122177n;
const MAX = 511;

const input = require('fs').readFileSync(0, 'utf-8').trim().split(/\s+/);
let idx = 0;
const nextInt = () => parseInt(input[idx++]);

const n = nextInt();
const k = nextInt();

if (n === 1) {
    console.log(0);
    process.exit(0);
}

let dp = Array.from({ length: MAX }, () => Array(MAX).fill(0n));
dp[1][1] = 2n;

const lim = Math.min(n, k);

for (let pos = 0; pos < n; pos++) {
    let ndp = Array.from({ length: MAX }, () => Array(MAX).fill(0n));

    for (let i = 1; i <= lim; i++) {
        for (let j = 1; j <= lim; j++) {
            const val = dp[i][j];
            if (val === 0n) continue;
            const nm = Math.max(i, j + 1);
            if (nm < MAX && j + 1 < MAX) {
                ndp[nm][j + 1] = (ndp[nm][j + 1] + val) % MOD;
            }
            if (i < MAX) {
                ndp[i][1] = (ndp[i][1] + val) % MOD;
            }
        }
    }
    if (pos !== n - 1) dp = ndp;
}

let nums = Array(MAX).fill(0n);
for (let i = 1; i <= lim; i++) {
    for (let j = 1; j <= lim; j++) {
        nums[i] = (nums[i] + dp[i][j]) % MOD;
    }
}

let div2 = Array(MAX).fill(0n);
for (let i = 1; i <= n; i++) {
    div2[i] = (nums[i] * INV) % MOD;
}

let res = 0n;
for (let i = 1; i <= lim; i++) {
    for (let j = 1; j <= lim; j++) {
        if (i * j < k) {
            res = (res + 2n * div2[i] * div2[j]) % MOD;
        }
    }
}

console.log(res.toString());

