    const limit = Math.min(k, n);
    for (let pos = 0; pos < n; pos++) {
        let ndp = Array.from({ length: MAX }, () => Array(MAX).fill(0n));
        for (let i = 1; i <= limit; i++) {
            for (let j = 1; j <= limit; j++) {
                const val = dp[i][j];
                if (val === 0n) continue;
                const nm = Math.max(i, j + 1);
                if (nm < MAX) {
                    ndp[nm][j + 1] = add(ndp[nm][j + 1], val);
                }
                ndp[i][1] = add(ndp[i][1], val);
            }
        }
        if (pos !== n - 1) {
            dp = ndp;
        }
    }

    let nums = Array(MAX).fill(0n);
